// Extract the top 50 institutions from CSRankings
const institutions = await browserjs(csTab, () => {
  // CSRankings table rows
  const rows = document.querySelectorAll("#ranking tbody tr");
  const list = [];
  rows.forEach(tr => {
    // each institution row typically has a rank, name, etc.
    const rankEl = tr.querySelector("td:nth-child(1)");
    const nameEl = tr.querySelector("td:nth-child(2) span");
    const countEl = tr.querySelector("td:nth-child(3)");
    if (nameEl) {
      list.push({
        rank: rankEl?.innerText?.trim(),
        name: nameEl?.innerText?.trim(),
        facultyCount: countEl?.innerText?.trim()
      });
    }
  });
  return list;
});

console.log("Found institutions count:", institutions.length);
console.log("Top 55 institutions:", institutions.slice(0, 55));

