const csTab = 103795432;
const schools = await browserjs(csTab, () => {
  const trs = Array.from(document.querySelectorAll("#ranking tbody tr"));
  const results = [];
  trs.forEach(tr => {
    const rankTd = tr.querySelector("td.rank-cell");
    if (!rankTd) return;
    const rank = rankTd.innerText.trim();
    // find school name and dept link
    const nameSpan = tr.querySelector("td:nth-child(2) span[onclick*='toggleFaculty']:not([id*='widget'])");
    const linkA = tr.querySelector("td:nth-child(2) a[href]");
    results.push({
      rank: rank,
      name: nameSpan ? nameSpan.innerText.trim() : "",
      deptUrl: linkA ? linkA.href : ""
    });
  });
  return results;
});

