function extractMain(html) {
  let clean = html.replace(/<script\b[^<]*(?:(?!<\/script>)<[^<]*)*<\/script>/gi, '')
                  .replace(/<style\b[^<]*(?:(?!<\/style>)<[^<]*)*<\/style>/gi, '');
  const m = clean.match(/<main[^>]*>([\s\S]*?)<\/main>/i) ||
            clean.match(/<article[^>]*>([\s\S]*?)<\/article>/i) ||
            clean.match(/<div[^>]+id=["']content["'][^>]*>([\s\S]*?)<\/div>/i);
  const target = m ? m[1] : clean;
  return target.replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ');
}

// 16. UW-Madison
const wiscHtml = (await tool.fetch_url({ url: "https://www.cs.wisc.edu/people/faculty-staff-recruitment/" })).body;
console.log("=== 16. UW-Madison ===\n", extractMain(wiscHtml).slice(0, 1500));

// 18. UPenn
const upennHtml = (await tool.fetch_url({ url: "https://www.cis.upenn.edu/open-faculty-positions/" })).body;
console.log("=== 18. UPenn ===\n", extractMain(upennHtml).slice(0, 1500));

// 19. Columbia
const columbiaHtml = (await tool.fetch_url({ url: "https://www.cs.columbia.edu/open-positions/" })).body;
console.log("=== 19. Columbia ===\n", extractMain(columbiaHtml).slice(0, 1500));

// 20. UCLA
const uclaHtml = (await tool.fetch_url({ url: "https://www.cs.ucla.edu/faculty-recruitment-academic-and-staff-positions/" })).body;
console.log("=== 20. UCLA ===\n", extractMain(uclaHtml).slice(0, 1500));

// 17. Princeton search
const searchTab = 103795220;
const enc = encodeURIComponent("site:cs.princeton.edu faculty hiring tenure track 2026 OR 2027");
await tool.navigate({ tabId: searchTab, url: `https://html.duckduckgo.com/html/?q=${enc}` });
await tool.wait_for({ tabId: searchTab, condition: "dom_settled", timeout_ms: 4000 });
const princetonLinks = await browserjs(searchTab, () => {
  return Array.from(document.querySelectorAll(".result__title a.result__url, .result__a")).map(a => {
    let realUrl = a.href;
    try {
      const u = new URL(a.href);
      if (u.searchParams.has("uddg")) realUrl = decodeURIComponent(u.searchParams.get("uddg"));
    } catch (e) {}
    return { title: a.innerText?.trim(), url: realUrl };
  }).filter(x => x.title && x.url && !x.url.includes("duckduckgo.com"));
});
console.log("=== 17. Princeton Links ===\n", princetonLinks.slice(0, 3));

