const searchTab = 103795220;

async function searchDDG(query) {
  const enc = encodeURIComponent(query);
  await tool.navigate({ tabId: searchTab, url: `https://html.duckduckgo.com/html/?q=${enc}` });
  await tool.wait_for({ tabId: searchTab, condition: "dom_settled", timeout_ms: 4000 });
  return await browserjs(searchTab, () => {
    return Array.from(document.querySelectorAll(".result__title a.result__url, .result__a")).map(a => {
      let realUrl = a.href;
      try {
        const u = new URL(a.href);
        if (u.searchParams.has("uddg")) realUrl = decodeURIComponent(u.searchParams.get("uddg"));
      } catch (e) {}
      return { title: a.innerText?.trim(), url: realUrl };
    }).filter(x => x.title && x.url && !x.url.includes("duckduckgo.com"));
  });
}

// 26. Northwestern
const nw = await searchDDG("Northwestern computer science faculty hiring tenure track");
console.log("26. Northwestern:", nw.slice(0, 2));

// 27. UC Riverside
const ucr = await searchDDG("UC Riverside computer science faculty recruit tenure track JPF");
console.log("27. UCR:", ucr.slice(0, 2));

// 28. UVA
const uva = await searchDDG("University of Virginia computer science faculty hiring tenure track");
console.log("28. UVA:", uva.slice(0, 2));

// 29. Utah
const utah = await searchDDG("University of Utah Kahlert School of Computing faculty hiring tenure track");
console.log("29. Utah:", utah.slice(0, 2));

// 30. Duke
const duke = await searchDDG("Duke computer science faculty hiring tenure track");
console.log("30. Duke:", duke.slice(0, 2));

